def compute(vars):
    old_value = vars["v1"]
    new_value = vars["v2"]

    if old_value == 0:
        return None

    change = new_value - old_value
    change_ratio_percentage = (change / old_value) * 100

    return {
        "value": change_ratio_percentage,
        "trace": {
            "old_value": old_value,
            "new_value": new_value,
            "change": change,
            "change_ratio_percentage": change_ratio_percentage,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
